mapper.select:
select sl.class_path, sl.business_id, to_char(sl.create_time,'yyyy-MM-dd hh24:mi:ss') as create_time, max(sl.create_user_name) as create_user_name, array_to_string(array_agg(DISTINCT sl.operation),',') as operation, array_to_string(array_agg(DISTINCT sl.content),',') as content from sys_log sl
AND sl.class_path in
#{classPath}
AND sl.business_id = #{params.businessId}
AND sl.pid = #{params.pid}
group by sl.class_path,sl.business_id,to_char(sl.create_time,'yyyy-MM-dd hh24:mi:ss') order by to_char(sl.create_time,'yyyy-MM-dd hh24:mi:ss') desc

select sl.class_path, sl.business_id, sl.create_time as create_time, max(sl.create_user_name) as create_user_name, array_to_string(array_agg(DISTINCT sl.operation),',') as operation, array_to_string(array_agg(DISTINCT sl.content),',') as content from sys_log sl
AND sl.class_path in
#{classPath}
AND sl.business_id = #{params.businessId}
AND sl.pid = #{params.pid}
group by sl.class_path,sl.business_id,sl.create_time order by sl.create_time desc
